(function(){if(!window.CET_DATA)window.CET_DATA={meta:{},exams:[]};window.CET_DATA.exams.push({"id":"2024-12-cet6-1","level":"CET6","year":2024,"month":12,"set":1,"title":"2024 �� 12 �� �� CET6 �� 1 ��","source":"��ѧӢ��CET6���� 2024 �� 12 �����⣨�� 1 �ף�","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"To\nincrease the likelihood of success, one should set realistic goals and work persistently towards them, \" You\ncan make comments, cite examples or use your personal experiences to develop your essay. You should write at\nleast 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard.","questions":[{"n":1,"options":{"A":"Preparing for a job interview.","B":"Writing a work report together.","C":"Going through a couple of issues the company faces.","D":"Discussing the woman's annual performance review."},"answer":""},{"n":2,"options":{"A":"The overall culture of the company.","C":"The honesty of the manager.","B":"The instruction from her supervisor.","D":"The recognition of her merits."},"answer":""},{"n":3,"options":{"A":"Her inadequate language proficiency.","B":"Her inability to interact with colleagues properly.","C":"Her inappropriate behavior at company meetings.","D":"Her simplistic approach to dealing with others."},"answer":""},{"n":4,"options":{"A":"To avoid offending the recipients.","C":"To save time.","B":"To show her unique writing style.","D":"To be frank."},"answer":""},{"n":5,"options":{"A":"Provide medical service to the community.","C":"Obtain a doctoral degree in internal medicine.","B":"Make healthcare in her hometown the best.","D":"Have a profound impact on people around her."},"answer":""},{"n":6,"options":{"A":"They have constantly urged her to study hard.","B":"They have worked hard to finance her education.","C":"They have tried to create a positive learning environment.","D":"They have pursued the family's dreams together with her."},"answer":""},{"n":7,"options":{"A":"It is a key medical branch conducive to realizing her dreams.","B":"It connects many other specialties with its broad coverage.","C":"It has a long history in the man's prestigious institution.","D":"It is a medical branch both of her parents specialize in."},"answer":""},{"n":8,"options":{"A":"Problematic.","C":"Inconsistent.","B":"Competitive.","D":"Trustworthy."},"answer":""}]},{"intro":"Questions 9 to 11 are based on the passage you have just heard.","questions":[{"n":9,"options":{"A":"To prevent hackers from cracking our secret codes.","B":"To show that all the guidelines are being followed.","C":"To provide evidence that passwords are forgotten.","D":"To convince our computer that we are human."},"answer":""},{"n":10,"options":{"A":"Put an end to the hacking phenomenon.","C":"Reduce the intricacy of the password itself.","B":"Help people remember their passwords.","D":"Explain the need for different email accounts."},"answer":""},{"n":11,"options":{"A":"Innovate technologies to ensure the safety of users' accounts.","B":"Provide incentives for the application of creative passwords.","C":"Explore the possibility of using simpler secret codes.","D":"Take steps to encourage users to log in more often."},"answer":""},{"n":12,"options":{"A":"Her work no longer interested her.","C":"Her fitness fell into a slump.","B":"Her training app did not fit her.","D":"Her business deteriorated."},"answer":""},{"n":13,"options":{"A":"Help users keep track of their fitness levels.","C":"Strengthen ties among users worldwide.","B":"Design personalised training programmes.","D":"Select well-qualified human coaches."},"answer":""},{"n":14,"options":{"A":"They are never repeated.","C":"They are of no extreme intensity.","B":"They help enrich her life.","D":"They keep her focused on her goal."},"answer":""},{"n":15,"options":{"A":"They will not be able to take the place of human personal trainers.","B":"They will not be able to comprehend some of the profiles users put in.","C":"They cannot lead to optimal results with their mathematical approach.","D":"They cannot match humans in arranging meticulous workout schedules."},"answer":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard.","questions":[{"n":16,"options":{"A":"All societies are built upon the cornerstones of basic values.","B":"Everyone everywhere demonstrates seven character traits.","C":"All societies are kept together by seven basic moral rules.","D":"Everyone everywhere shares a universal moral standard."},"answer":""},{"n":17,"options":{"A":"Ascertain whether deferring to authority was confined to right-wing people.","B":"Find out whether different societies had different versions of morality.","C":"Make clear whether all societies faced the same moral issues.","D":"Find out whether left-wing people still had a group loyalty."},"answer":""},{"n":18,"options":{"A":"Make independent descriptions of cultures around the world.","B":"Strive to understand the basic differences between peoples.","C":"Appreciate the foundational value of the existing data.","D":"Carry out systematic field studies to gather new data."},"answer":""},{"n":19,"options":{"A":"They might be the most important part of our eating experience.","B":"They can activate our brain functions in a most direct fashion.","C":"They can be viewed as the windows to our soul.","D":"They could mislead us in more ways than one."},"answer":""},{"n":20,"options":{"A":"It attracts food companies' growing attention.","C":"It invariably determines how food sells.","B":"It adversely impacts one's eating experience.","D":"It changes the way people taste food."},"answer":""},{"n":21,"options":{"A":"Enhance the taste.","C":"Identify distinct flavors.","B":"Make predictions.","D":"Enrich the eating experience."},"answer":""},{"n":22,"options":{"A":"Social status.","C":"Meaning.","B":"Financial resources.","D":"Happiness."},"answer":""},{"n":23,"options":{"A":"Their effect on people's happiness has long been overstated.","B":"Their influence on people's life varies with social contexts.","C":"They can affect people's experience of meaning.","D":"They can ensure people's overall well-being."},"answer":""},{"n":24,"options":{"A":"It used questions totally different from those in their first study.","B":"It focused on the sense of meaning of French participants.","C":"It analysed cases from a daily poll of US residents.","D":"It examined data collected from multiple countries."},"answer":""},{"n":25,"options":{"A":"They might have more access to external sources of happiness.","B":"They might focus on an individual sense of satisfaction or meaning.","C":"They might be less easily affected by a community's overall feeling.","D":"They might be less adversely impacted by failure to achieve a purpose."},"answer":""}]}]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each\nblank from a list of choices given in a word bank following the passage. Read the passage through carefully\nbefore making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding\nletter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words\nin the bank more than once.\n\n     With the rapid progress in the economy, it is natural that people's ideology is bound for change. Being\n___26___ is no longer a virtue to some people, and they are not alone in holding this view. Each might have\ndifferent viewpoints on how to lead one's lifestyle: some prefer simplicity, some love luxuries, some spend\n___27___, some accumulate as much as they can like a country mouse. As I was born poor and in the\ncountryside, the simple rural life seldom loses its ___28___ to me, but as my station changes, I have an\nopportunity to ___29___ with the newly rich, an experience which has revolutionized my view of lifestyle.\n\n                                  2024 �� 12 ��Ӣ����������� 1 ��             �� 3 ҳ���� 9 ҳ\n\n    It is evil or sinful to spend little and to save much, an idea only recently being revealed to me. Actually the\nwhole world is in a ___30___ to borrow and to spend, with the USA leading the trend. The USA is still the\nrichest and most powerful country in the world, but the ___31___ is that they borrow money from us. Though a\n___32___ of economics, at least I know that investing with borrowed money will turn the borrower into the\n___33___ rather than the decent and kind lender. An apparent case is real estate. Those who are ___34___ and\nhave got loans from the bank become relatively rich by selling their purchased home at a price several folds\nhigher. Even education is not immune from this theory. Many of those poor parents who have the vision to send\ntheir children to college have benefited from this investment, even though they have to ___35___ a living. It is\nreasonable to conclude that spending is praiseworthy. supposing it is not beyond your means.","bank":[["A","appeal"],["I","meadow"],["B","extravagantly"],["J","mingle"],["C","intrinsically"],["K","predator"],["D","irony"],["L","rage"],["E","layman"],["M","scrape"],["F","literally"],["N","shrewd"],["G","majestic"],["O","thrifty"],["H","malicious"]],"answers":{}},"matching":{"statements":[{"n":36,"text":"According to a senior researcher, we will have secure food supply if we rid ourselves of ignorance about\n   native crops.","answer":""},{"n":37,"text":"Most of the world's food supply comes from a tiny number out of thousands of crops that have been grown\n   for centuries.","answer":""},{"n":38,"text":"To provide their family with food when the staple crops failed, some African women farmers grew local\n   crops in their backyards.","answer":""},{"n":39,"text":"High-yielding crops have occupied a dominant position in modern agriculture since the green revolution in\n   the last century.","answer":""},{"n":40,"text":"Growing alternative crops proved feasible in a variety of environments, but the critical question was\n   whether they would be marketable.","answer":""},{"n":41,"text":"According to a professor, when the yields of staple crops fall, we will have to adapt to eating foods from\n   alternative crops.","answer":""},{"n":42,"text":"Urgent measures have to be taken to provide food for the projected world population without aggravating\n   the climate.","answer":""},{"n":43,"text":"Colonial rule marginalised local crops by punishing Africans who grew them.","answer":""},{"n":44,"text":"As existing crops are endangered by global warming, we can increase food security by bringing back the\n   many forgotten food crops.","answer":""},{"n":45,"text":"Researchers are trying to find out how higher temperatures and CO, levels affect the nutritional composition\n   of alternative crops.\n                                 2024 �� 12 ��Ӣ����������� 1 ��           �� 6 ҳ���� 9 ҳ","answer":""}],"note":"�����𰸼��ѽ��룻��������������롣"},"reading":[{"title":"Passage One","passage":"Imagine you're an alien sent to Earth to document the behaviour of the mammals inhabiting the planet.\nYou stumble into a movie theatre that's showing the latest Hollywood horror film.\n     Several dozen humans are gathered together in a dark, undecorated room. They're all staring at a\nrectangular area on which patterns of light change rapidly.\n     They are clearly in a state of high arousal. Their heart rate is elevated, they occasionally glance around\nnervously, and they sometimes jump collectively in their seats, and emit high-pitched warning calls.\n     Eventually, the lights come up and the rectangular screen goes black. The humans stand up and leave the\nroom, chatting and laughing, and showing signs of pleasure.\n     Why do these humans voluntarily expose themselves to what appears to be a deeply unpleasant\nexperience? And why do they react so strongly to those patterns of light on a screen?\n     I am fascinated with the paradox of horror-the strange fact that many people seek out scary entertainment.\n     I think the answer to the puzzle lies in human nature.\n     My research suggests that we humans evolved to find pleasure in situations that allow us to experience\nnegative emotions in a safe context. You can see these elements of horror in children's games. Take\nhide-and-seek for example, which is a simulation of a predator-prey interaction. The kid hides and the adult\npretends to be a predator, searching for the child while howling like a dangerous beast.\n     This simulation gives the child crucial information about how to avoid becoming prey, and children tend\nto find that kind of activity deeply satisfying, presumably because it gives them a safe experience of a\npotentially catastrophic scenario.\n     They find it pleasurable, and pleasure is evolution's way of motivating us toward adaptive behaviour.\n     Horror is pleasurable to many people because it lets us play with negative emotions and develop coping\nstrategies. We learn what it feels like to be truly afraid, and we learn how to handle negative emotion.\n     How, then, does horror work? My research suggests that horror works by exploiting an ancient set of\nbiological defence mechanisms-an evolved fear system, which we share with other animals. But humans are\nuniquely imaginative, and we use our evolved imagination to travel into virtual worlds that are full of danger.\n     There are good reasons for watching a horror film, even if you're not a loyal horror fan. If you make it\nthrough the film in one piece, you'll probably experience a strong sense of mastery, a sense that you were able\nto make it through an appalling experience. Anyway, watching a horror film makes you better at handling your\nown fear, and who knows when that will become critically relevant?","questions":[{"n":46,"stem":"The alien finds the audience in the movie theatre clearly in a state of ______.","options":{"A":"total mindfulness","C":"spiritual elevation","B":"extreme excitement","D":"intense curiosity"},"answer":""},{"n":47,"stem":"Why do many people seek out scary entertainment, according to the author's research?","options":{"A":"They gain experience in overcoming horror in real life.","B":"They find joy in going through simulated horrible experiences.","C":"They have learned from hide-and-seek as kids the thrill involved.","D":"They have evolved to gain pleasure in escaping life-threatening situations."},"answer":""},{"n":48,"stem":"What do children learn from hide-and-seek?","options":{"A":"How to avoid falling prey to an attacker.","B":"How to simulate a predator-prey interaction.","C":"How to keep themselves from catastrophic errors.","D":"How to turn a dangerous scenario into a safe one."},"answer":""},{"n":49,"stem":"Why is horror gratifying to many people?","options":{"A":"It reminds them of an ancient set of biological defence mechanisms.","B":"It triggers their imagination to travel into dangerous virtual worlds.","C":"It allows them to learn what fear feels like and how to tackle it.","D":"It activates their evolved fear system and their unique fantasy."},"answer":""},{"n":50,"stem":"What will one experience if they watch a horror film through without being hurt?","options":{"A":"A strong sense of clear relevance.","C":"A profound sense of intense relief.","B":"A profound sense of good fortune.","D":"A strong sense of being in control."},"answer":""}]},{"title":"Passage Two","passage":"An awakening has been taking place in the physical world against the beauty model that has been dictated\nto us for years. But in the digital arena, social media determines what is considered beautiful.\n     The two opposing struggles are taking place in parallel. In the physical world, the struggle goes against the\nunderlying pressure exerted on women to conform to an unrealistic beauty ideal. As part of the struggle,\nvarious media outlets have presented women whose bodies don't correspond to the so-called ideal. All those\nwomen who had previously been excluded from the covers of magazines, television series and the public\nagenda, have become \"legitimate\". At the same time, a group of influencers have begun to upload to social\nmedia photos of themselves without makeup, and even photos in which they highlight supposed flaws.\n     Technology has reshaped our beauty ideal and is doing a great job communicating that message to the\nmasses. One of the bizarre legacies of the past decade is the popularity of the \"cyborg look\", which illustrates\nwhat Americans will look like in 2050.\n     The cyborg look spread rapidly. Today, however, the Instagram face has become the new beauty ideal.\n     The internalization of accepted beauty norms is much more effective when there is active involvement in\nthe learning process. The active involvement of users is reflected in the gamified ( �� Ϸ �� �� ) interaction\noffered by the social media platforms-the ability to like, write a comment, compare, share.\n     Once the desired beauty ideal has been internalized, users are given tools or features to change their\nappearance to suit the accepted beauty ideal such as editing the image, choosing the ideal filter, the right\nbackground.\n     A survey conducted in the United States revealed that more than 50% filter the images before posting\nthem. And you will not be surprised to hear that the majority of them are women. One of the significant\nconsequences of obsessive filtering is the emerging tendency to treat oneself as an object to be observed and\nvalued, in the same way another person observes and judges from the side.\n     The effect of the filters is already far beyond amiable amusement. The filters and the entire game played\non the networks affect the mental health of the users. According to a study, apps like Instagram, Snapchat and\n                                 2024 �� 12 ��Ӣ����������� 1 ��            �� 8 ҳ���� 9 ҳ\n\nFaceTune allow users to achieve a level of perfection that was previously only observed in beauty magazines.\n     Even though humanity has always cherished beauty, in the last decade our obsession with looks has\nreached an unprecedented peak. The time spent on social media creates an urge to achieve an impossible beauty\nideal so powerful that the only thing that can fix it is not cosmetic intervention, but mental health care.","questions":[{"n":51,"stem":"What do we learn about beauty in the digital arena?","options":{"A":"It dictates the taste of digital media.","C":"It has ushered in a new awakening.","B":"It has been in the making for years.","D":"It is defined by social media."},"answer":""},{"n":52,"stem":"What does the passage say about beauty in the physical world?","options":{"A":"Women are under constant pressure to keep up with beauty models.","B":"Women are encouraged to pursue a beauty ideal that has never existed.","C":"A fight is going on to remove pressure on women to conform to an absurd beauty ideal.","D":"Media outlets have begun to present as beauty models trendy women without any makeup."},"answer":""},{"n":53,"stem":"What do we learn from the passage about the Instagram face?","options":{"A":"It is now regarded as the new beauty ideal.","B":"It is what most women will go after in 2050.","C":"It is being much talked about on social media.","D":"It is a perfect illustration of the ultimate beauty."},"answer":""},{"n":54,"stem":"What has obsessive filtering resulted in?","options":{"A":"A good many women striving to reach an impossible level of perfection.","B":"An urge to turn the entire game played on the network to one's advantage.","C":"A tendency to regard one's body as an object of observation and judgment.","D":"An increasing number of women filtering their images before uploading them."},"answer":""},{"n":55,"stem":"What does the author want to emphasize at the end of the passage regarding Americans' obsession with","options":{"A":"Cosmetic surgery should be made more accessible to the masses.","B":"Psychological intervention should be introduced to alleviate it.","C":"Their time spent on social media should be strictly controlled.","D":"Its root cause should be meticulously examined and analyzed."},"answer":""}]}],"translation":{"prompt":"","guide":[]}});window.CET_DATA.exams.push({"id":"2024-12-cet6-2","level":"CET6","year":2024,"month":12,"set":2,"title":"2024 �� 12 �� �� CET6 �� 2 ��","source":"��ѧӢ��CET6���� 2024 �� 12 �����⣨�� 2 �ף�","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence\n\"Nowadays, more and more students have realized the importance of self-discipline in their personal\ngrowth.\" You can make comments, cite examples or use your personal experiences to develop your essay. You\nshould write at least 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard.","questions":[{"n":1,"options":{"A":"Changing his major.","C":"Revising his graduation thesis.","B":"His family situation.","D":"His passion for Art History."},"answer":""},{"n":2,"options":{"A":"He doesn't think it legitimate to depend on his father.","B":"He thinks his financial situation has now changed.","C":"He doesn't think it will provide him with a living.","D":"He thinks it nourishes the financially secure only."},"answer":""},{"n":3,"options":{"A":"Try his best to socialize and build a network in the art industry.","B":"Seek financially viable employment opportunities after graduation.","C":"Investigate all possible ways to become a celebrity in the art world.","D":"Strike a balance between intellectual pursuits and financial security."},"answer":""},{"n":4,"options":{"A":"Money.","B":"Time.","C":"Determination.","D":"Optimism."},"answer":""},{"n":5,"options":{"A":"Their decision on investigating beef consumption.","B":"Their original ideas about the domestic market.","C":"Their different approaches to a case study.","D":"Their end-of-semester business projects."},"answer":""},{"n":6,"options":{"A":"Expanding farmland out west.","C":"Raising cattle domestically.","B":"Importing most of the beef.","D":"Continuing to boost economic growth."},"answer":""},{"n":7,"options":{"A":"Technical equipment.","C":"Beef.","B":"Business consultancy.","D":"Carwashing."},"answer":""},{"n":8,"options":{"A":"Car owners of all walks of life.","B":"High-end customers in big cities.","C":"Consumers craving for professional service.","D":"Well-off dealers seeking a profitable markup."},"answer":""}]},{"intro":"Questions 9 to 11 are based on the passage you have just heard,","questions":[{"n":9,"options":{"A":"Parents' talking with them during TV time raises their curiosity levels.","B":"Their daily television exposure cuts parent-child conversation time.","C":"The more TV they watch the poorer their progress in development.","D":"Their socioeconomic levels impact their academic achievement."},"answer":""},{"n":11,"options":{"A":"It can hinder kids from getting on with their peers.","B":"It can cut into kids' time on exploratory activities.","C":"It can arouse kids' interest in how people interact in real life.","D":"It can widen the gap between kids from different economic statuses."},"answer":""},{"n":12,"options":{"A":"Exerting ourselves too hard in order to attain our life's goals.","B":"Being possessed with a single thought of professional success.","C":"Trying every means to beat others in terms of personal aspirations.","D":"Being mindlessly driven to possess more and more material things."},"answer":""},{"n":13,"options":{"A":"We might isolate ourselves from our fellow beings.","B":"We might acquire an incorrect sense of well-being.","C":"We might end up pursuing all the wrong things.","D":"We might make a mess of our personal lives."},"answer":""},{"n":14,"options":{"A":"They should be based on solid theoretical concepts.","B":"They should take personal interests into account.","C":"They should include goals to help other people.","D":"They should increase our sense of worthiness."},"answer":""},{"n":15,"options":{"A":"Drifting through life aimlessly.","C":"Abandoning all that life has to offer.","B":"Giving up the chance to fulfill yourself.","D":"Spoiling your character and integrity."},"answer":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard.","questions":[{"n":16,"options":{"A":"Grade-raising ways and means.","C":"Revision-conducting approaches.","B":"Pressure-alleviating exercise.","D":"Brain-boosting food and drink."},"answer":""},{"n":17,"options":{"A":"Buying it from coffee shops.","C":"Drinking it after 2 pm.","B":"Building up a tolerance of it.","D":"Consuming it with sugar."},"answer":""},{"n":18,"options":{"A":"By taking varied vitamin supplements.","C":"By eating both oranges and frozen berries.","B":"By consuming a rich variety of foods.","D":"By getting components packaged in tablets."},"answer":""},{"n":19,"options":{"A":"Many people across advanced economies think the world is going from bad to worse.","B":"The news focuses on reporting catastrophes that occur across the world.","C":"A significant part of the world is experiencing another great recession.","D":"Many people have no idea of those living under miserable conditions."},"answer":""},{"n":20,"options":{"A":"It has experienced ups and downs like any other historical trend.","B":"It is hailed as a miracle by both economists and ordinary people.","C":"It is the only way for all countries to share economic prosperity.","D":"It has given more and more countries a rare chance to thrive."},"answer":""},{"n":21,"options":{"A":"Their fortunes may take a downturn.","B":"They can be classified as middle class.","C":"Their living standards have been deteriorating.","D":"They are experiencing a radical transformation."},"answer":""},{"n":22,"options":{"A":"Why smells can activate emotional memories.","B":"How powerful the sense of smell can become.","C":"How scent particles revive memories forgotten.","D":"Why the scent of bread has a strong mental impact."},"answer":""},{"n":23,"options":{"A":"The brain cells' processing of memories experienced as strongly emotional.","B":"The activation of the brain's emotion processing area by chemical particles.","C":"The interaction between chemical particles and the brain cells responsible for smell.","D":"The sensations of scents going directly to the brain's emotional and memory centers."},"answer":""},{"n":24,"options":{"A":"Imagination.","B":"Association.","C":"Experience.","D":"Context."},"answer":""},{"n":25,"options":{"A":"Inaccuracy and alterability.","C":"Being personal and individualistic.","B":"Susceptibility to polar interpretations.","D":"Being dependent on relevant scenarios."},"answer":""}]}]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each\nblank from a list of choices given in a word bank following the passage. Read the passage through carefully\nbefore making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding\nletter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words\nin the bank more than once.\n     Ever been talking about something important with someone you care about and found the discussion\nfrustrating instead of fruitful? Negative energy can then cast a ___26___ over your efforts to build a shared\nunderstanding.\n     In fact collaborative problem-solving conversations require skills. Strong listening skills are essential.\nSprinkling in positivity via appreciation, ___27___ smiles, and warm comments helps. So does the essential\nability to keep your emotional tone in the calm zone. If the tone of a dialogue heats up and anger erupts, the\ndialogue ___28___ from collaborative to adversarial, and progress is likely to come to an immediate ___29___.\n     In addition, effective dialogue generally has another important characteristic: symmetry.\n     Symmetry in dialogue refers to the balance of how much each partner talks. Are you each getting equal\nairtime? When one participant does most of the talking, this asymmetry or lack of balance tends to become\n\n                                 2024 �� 12 ��Ӣ����������� 2 ��           �� 3 ҳ���� 9 ҳ\n\nannoying to one or both of you. The silent partner ___30__ tires of only listening, while the talker can feel\n___31___. Usually, both would prefer more equal give and take.\n     Different rates of speech and levels of voice volume can ___32___ symmetry as well. The faster or louder\npartner can easily begin taking up more airtime. The slower-talking or softer-voiced one can have trouble\ngetting the floor.\n     Conversations also lose balance when one partner's opinions count more than the other's. One person's\ninput may carry more sway because their style of expression is more ___33___. One viewpoint may tend to get\nlost because it is expressed more ___34___.\n     If either partner fairly consistently ___35___ or evaporates, modifying the pattern will be helpful. The\ndialogue will feel more productive, and at the same time, the relationship overall is likely to feel more positive.","bank":[["A","affectionate"],["I","predominates"],["B","approximately"],["J","propagate"],["C","elapses"],["K","scenario"],["D","erode"],["L","shadow"],["E","flattered"],["M","tentatively"],["F","flips"],["N","typically"],["G","halt"],["O","vigorous"],["H","overburdened"]],"answers":{}},"matching":{"statements":[{"n":36,"text":"We cannot see the moon at times when it is positioned right between the earth and the sun.","answer":""},{"n":37,"text":"Volcanic eruptions may cause the moon to assume a moody blue color.","answer":""},{"n":38,"text":"The moon will be closest to the earth when the supermoon occurs in February.","answer":""},{"n":39,"text":"There is nothing unusual about the super blood wolf moon, which will bear no resemblance to a bloody\n   wolf head.","answer":""},{"n":40,"text":"The moon will appear orange when the light reflecting from it travels through an atmosphere thicker than\n   usual.","answer":""},{"n":41,"text":"It is contrary to logic to claim the name of wolf moon originates from the cultures of American Indians.","answer":""},{"n":42,"text":"As the moon's orbit is not a hundred-percent circle, its distance from the earth changes.","answer":""},{"n":43,"text":"A full moon in a given month or season gets a specific name in different cultures.","answer":""},{"n":44,"text":"There are likely lots of people who know absolutely nothing about why the moon appears to change its size\n   regularly but act like they know.","answer":""},{"n":45,"text":"When a full moon appears twice in the same month, it is nicknamed a blue moon.","answer":""}],"note":"�����𰸼��ѽ��룻��������������롣"},"reading":[{"title":"Passage One","passage":"With population increases and global urbanisation ever accelerating, much attention is focused on the\nsustainability of our cities and scarce attention is paid to the countryside.\n     Rural life is associated with closely-knit communities, sense of belonging, and a simple, tranquil life. Yet\n\n                                  2024 �� 12 ��Ӣ����������� 2 ��            �� 6 ҳ���� 9 ҳ\n\nwhilst some or all of these elements exist in the countryside, so do conservatism and a lack of employment\nopportunities. And it is mostly due to the latter that rural communities are suffering. Attracted by the improved\neconomics of urban areas, country-dwellers across the world are moving out, contributing to the excessive\ncrowdedness of densely populated cities, and leaving the countryside in desolation.\n     So how can the countryside ensure its survival among these changes; or should it at all? Due to both the\ndistance between residences and facilities and often intermittent public transport, those living in the countryside\nare heavier automobile users. Rural dwellers also use more energy maintaining their mostly detached buildings.\nWe may be piled up like boxes in the city, but this brings energy efficiency that the countryside cannot match.\nRural energy requirements result in higher carbon emissions per person than in the city, so it is actually\nirresponsible to endorse such a lifestyle choice.\n     Protecting the countryside is a hot topic. Those who have made their fortunes in the city often buy second\nhomes in the countryside, visiting intermittently for a sample of a supposedly simple life. The side-effect of this\nis that house prices are pushed up due to increased demand, leaving them unaffordable for local people. A\nsolution has yet to be found for this challenge, for market forces are further forcing residents out of the\ncountryside. For those who believe in rural preservation, this is deplorable.\n     Whilst an idealised view of the countryside is common, the reality is that rural life has continuously\nevolved. Industrialisation brought an increase in divisions of labour, changing social links between rural\npeople. The internet has introduced once foreign cultures into the countryside. Improved travel connections and\naffordability have made the world more accessible, creating a \"global village\". Considering these changes,\nsurely an evolving countryside is inevitable.\n     Perhaps the countryside should also prepare itself for massive population increases in the future. With\ncities across the world growing rapidly, how will the current urban generation respond to the inevitable social\nchanges of mass urbanisation? Will the longing for a simpler life become stronger, fueling a rural renaissance?\n     As the world continues to urbanise, the voices calling for rural preservation may well grow louder. But\nchange is inevitable. We know that the world is going to see new cities emerging from the dust and current\ncities growing into megacities. but the future of the countryside is less clear.","questions":[{"n":46,"stem":"What has become of the rural areas nowadays?","options":{"A":"They are becoming somewhat deserted.","C":"They are closely-knit communities.","B":"They are being increasingly urbanised.","D":"They are haunted by conservatism."},"answer":""},{"n":47,"stem":"What does the author think of the rural lifestyle?","options":{"A":"It is unlikely to survive given the on-going changes.","B":"It is less energy-efficient compared to that in cities.","C":"It is highly dependent upon heavy automobiles.","D":"It is a choice more affluent people will endorse."},"answer":""},{"n":48,"stem":"What does the author think of rich urban residents buying a second home in the countryside?","options":{"A":"It is bound to mar the traditional rural life.","B":"It adversely impacts rural social stability.","C":"It hinders rural economies' revitalisation.","D":"It is detrimental to rural preservation."},"answer":""},{"n":49,"stem":"What do we learn about the countryside with industrialisation and technological advances?","options":{"A":"It is destined to change gradually.","C":"It is likely to embrace foreign cultures.","B":"It will present an idealised way of life.","D":"It will become increasingly diversified."},"answer":""},{"n":50,"stem":"What does the author think of the future of the countryside compared with cities?","options":{"A":"It is going to be harder for the locals.","C":"It is less likely to stay static.","B":"It is going to resemble that of cities.","D":"It is less easy to envisage."},"answer":""}]},{"title":"Passage Two","passage":"Statements, like \"beauty is in the eye of the beholder (�ۿ���)\", are rarely questioned. They've become so\nembedded in our consciousness that people think it's absurd to think otherwise. It might be useful, however, to\nat least push back on this assumption because people evaluate environment, situations, and people aesthetically.\nWe may find that we still believe it is correct, but we may also find that there is a lot more to the situation than\nyou suppose.\n     A recent study exploring aesthetic taste was published in Cognition. The results from this study show that\npeople agree very much in their aesthetic evaluation of natural objects, but they disagree more about artifacts,\nor human-made objects.\n     The study found that shared taste was most common for faces and natural landscapes, but least common\namong works of architecture and art. The hypothesis is the commonly pleasing features, like proportion or\nsymmetry, are at work.\n     Preferences for natural scenes might be learned through life experiences. Factors like habitability, safety,\nand openness might be preferred as people develop. Some of the details of landscapes change, but the basics are\nmore common, e.g., water, open spaces, and signs of care.\n     Art and architecture, unlike natural spaces, do not have the same level of exposure. So, people do not have\nthe same level of shared taste.\n     It's possible that the lower amount of agreement in the shared taste of artifacts has to do more with\nelements of style, rather than \"behavioral consequences\".\n     All of the consequences seem reasonable (or at least possible), but I think there might be an interesting\nphilosophical conclusion that they did not draw. It seems that there is an objective ground to our aesthetic\npreferences or evaluations. I am not saying this would mean beauty is completely objective, just that there\ncould possibly be general objective principles at work, i.e., beauty is not simply in the eye of the beholder.\n     Nature exhibits some of the universal aesthetic features, such as radiance, in a common way throughout\nthe world. It's not exactly the same everywhere, but it is common. For example, a sunset is similar enough in\ndifferent places to warrant almost universal appeal.\n     Possible universal principles of beauty��such as proportion, fittingness, radiance, and others��are general\ncategories, which allow for a wide array of embodiments. When people get involved in making artifacts in\narchitecture or art, they apply these very general concepts in unique ways. But the way they applied the\nprinciple may not have universal appeal.\n     This is why it's important to experience diverse cultures and their artifacts because it opens us up to\ndifferent ways of approaching or constructing beauty. And it is always good to question our assumptions.\n\n                                  2024 �� 12 ��Ӣ����������� 2 ��           �� 8 ҳ���� 9 ҳ","questions":[{"n":51,"stem":"What does the passage say about the statement \"beauty is in the eye of the beholder\"?","options":{"A":"It has hardly ever been disputed.","C":"Many people have found it absurd.","B":"It can be interpreted aesthetically.","D":"People have long been misled by it."},"answer":""},{"n":52,"stem":"What does a recent study exploring aesthetic taste show?","options":{"A":"Aesthetic tastes tend to differ from person to person.","B":"Natural beauty is rarely surpassed by artificial beauty.","C":"There is less consensus on objects shaped by human craft.","D":"There is general agreement on what is pleasing to the eye."},"answer":""},{"n":53,"stem":"Why do people differ in their aesthetic appraisal of artifacts?","options":{"A":"They come out in a great variety of designs.","B":"They lead to varying behavioral consequences.","C":"They take up much less natural space than landscapes.","D":"They come into people's view less often than natural spaces."},"answer":""},{"n":54,"stem":"What does the example of sunset tell about nature?","options":{"A":"It creates a powerful appeal through its brilliant radiance.","B":"It displays aesthetic traits in a similar way the world over.","C":"It embodies beauty with a wide array of aesthetic features.","D":"It establishes the principles of beauty in a number of ways."},"answer":""},{"n":55,"stem":"Why do artifacts not always hold universal appeal?","options":{"A":"The appreciation of their beauty is not subject to objective standards.","B":"The universal principle of beauty prevents a wide array of embodiments.","C":"The way their creators apply the principle of beauty may not be pleasing to everybody.","D":"Their creators interpret the universal principle of beauty each in their preferred way."},"answer":""}]}],"translation":{"prompt":"","guide":[]}});window.CET_DATA.exams.push({"id":"2024-12-cet6-3","level":"CET6","year":2024,"month":12,"set":3,"title":"2024 年 12 月 · CET6 第 3 套","source":"大学英语CET6考试 2024 年 12 月真题（第 3 套）","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"College\nprovides a great opportunity for students to explore various possibilities and find the right path for\nthemselves. \" You can make comments, cite examples or use your personal experiences to develop your essay.\nYou should write at least 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each\nblank from a list of choices given in a word bank following the passage. Read the passage through carefully\nbefore making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding\nletter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words\nin the bank more than once.\n     About 23% of the global population lives in absolute poverty. In developing countries there is a low life\nexpectancy, a high infant ___26___ rate, high levels of unemployment and illiteracy, nutritional levels below\nacceptable standards and widespread disease with very little or poor quality medical assistance. Others live\n___27___ wealthy and luxurious lives and so the wealth is distributed in a very ___28___ manner. These are\nthe central problems to questions of charity though charity also includes many other areas such as assisting the\nelderly.\n     We all ___29___ when very rich people pledge to give away most of their billions, but they are usually\nleft with millions to pass on, still much more than most people would expect to earn in their lifetime. Even\ncomparatively ___30___ salaries in the west are very high when compared globally. Someone on £20,000\ncould easily afford to give away £ 2,000 per year and still have plenty to live on plus some luxuries.\n     Most people agree that giving to charity is morally ___31___ but charitable behaviour tends to be regarded\nas above and beyond the call of duty. Some argue, however, that charitable behaviour is morally required. This\nmeans that to fail to behave charitably would be wrong. The majority of arguments in this vein refer to giving\naid to poorer nations but they may also refer to giving time within one's ___32___ community. Arguments tend\nto place different requirements on people in different income brackets and ___33___ entirely people who are\nmerely making ends meet. Some argue that people should all contribute a certain percentage of their earnings. I\n                                 2024 年 12 月英语六级真题第 3 套           第 1 页，共 7 页\n\nwill ___34___ together all those arguments that place a moral requirement on people to give to charity, despite\nthe fact that there is wide disagreement as to the ___35___ of that moral requirement.","bank":[["A","applaud"],["I","moderate"],["B","casualty"],["J","mortality"],["C","exclude"],["K","overt"],["D","extent"],["L","praiseworthy"],["E","group"],["M","probe"],["F","hierarchical"],["N","sceptically"],["G","immediate"],["O","unequal"],["H","incredibly"]],"answers":{}},"matching":{"statements":[{"n":36,"text":"People became more and more reliant on others for basic needs as they entered the modern world even\n   though they might feel less so.","answer":""},{"n":37,"text":"On the topic of trade, productive debates might be possible, in contrast to the familiar mutual condemnation\n   in discussing other issues.","answer":""},{"n":38,"text":"We feel greater independence than we actually possess because money allows us to buy things without\n   building any relationships.","answer":""},{"n":39,"text":"The trouble with today's trade stems from misconceptions rather than money.","answer":""},{"n":40,"text":"For their arguments to prevail, advocates of free trade must try to forge bonds of affection between\n   consumers at home and producers overseas.","answer":""},{"n":41,"text":"According to Tocqueville, unlike our ancestors, we and the people we do trade with are strangers to each\n   other.","answer":""},{"n":42,"text":"In primitive societies, people had to rely mostly on themselves to meet their personal needs.","answer":""},{"n":43,"text":"Few commodities in American homes are not reliant on people abroad in the process of manufacture","answer":""},{"n":44,"text":"Protectionists argue against free trade by referring to the losses suffered by domestic producers and\n   communities.","answer":""},{"n":45,"text":"It is extremely hard to make people feel dependent on and grateful to strangers overseas.","answer":""}],"note":"题干与答案键已接入；完整段落后续补齐。"},"reading":[{"title":"Passage One","passage":"There are hundreds of personality quizzes online that assert they can ascertain whether the right or left half\nof your brain is dominant. Left-brained people are supposedly logical and excel at language and math while\nright-brained people are more imaginative, emotionally intelligent and skilled with spatial reasoning. There's\njust one problem: That's not how brains work.\n     Popular science enthusiasts sort of took this idea and ran with it, and it's become woven in popular culture\nnow, and it's not going away.\n\n                                 2024 年 12 月英语六级真题第 3 套           第 4 页，共 7 页\n\n     Despite this enduring belief, there's no such thing as being \"right-brained\" or \"left-brained\". Whether\nyou're someone who tends more towards creativity or logic has nothing to do with one hemisphere of your\nbrain being dominant over the other. But the actual science of how the two halves of our brains work together is\nsometimes stranger than fiction.\n     The human brain is divided into two hemispheres, the left and right. In all vertebrate (脊椎的) animals, the\nright hemisphere controls the left side of the body and vice versa. And scientists have long known, thanks to the\nbehaviors of patients who suffered brain injuries, that different areas of the brain do different things.\n     But many scientists struggled with this idea, because the very suggestion that the left and right halves of\nthe brain operate differently disrupted the idea that nature tends toward perfect symmetry.\n     Work by neuroscientists (神经科学家) has revealed the importance of different hemispheres of the brain\nfor different activities. However, their research quickly saw some misinterpretations in the general public:\nSome presumed creative people must be right-brained and logical people left-brained. It is proven that not only\nis personality unrelated to the different halves of the brain, but people aren't really right- or left-brained to begin\nwith. The idea that we have left-dominant people and right-dominant people, and that this is related to\npersonality, is categorically false. That's never been supported in the neuroscience community. Neuroscientists\ndon't believe that and never have.\n     What scientists learned is that there are really important differences between the left hemisphere and the\nright hemisphere. It's just that they have nothing to do with personality or whether cognitive strategy is more\nlogical or free spirited or creative. While researchers have shown the limitations of how the hemispheres of our\nbrains influence our lives, it's not difficult to understand the appeal of such ideas. People are endlessly\nfascinated by themselves and their friends, and the subtle differences in how people think about the world are\nreally meaningful to them. When you come up with an online quiz that tells us something about ourselves,\nwe're drawn to that. It's irresistible. But you have to take it with an enormous grain of salt.","questions":[{"n":46,"stem":"What do numerous personality quizzes online claim they are able to do?","options":{"A":"Distinguish between the two hemispheres of one's brain.","B":"Determine whether one is left-brained or right-brained.","C":"Tell if one is more of a linguist or of a mathematician.","D":"Ascertain how one's brain performs different tasks."},"answer":""},{"n":47,"stem":"What does the author say is sometimes stranger than fiction?","options":{"A":"How one hemisphere of the brain impacts creativity.","B":"How the two halves of our brains work alternately.","C":"How the two hemispheres of our brains cooperate.","D":"How one half of the brain dominates the other."},"answer":""},{"n":48,"stem":"Why did many scientists have difficulty endorsing the idea that different areas of the brain do different","options":{"A":"It contradicts the assumption that the two hemispheres of the brain are symmetrical.","B":"It dismisses the view that the universe has been evolving in a consistent manner.","C":"It is in conflict with the suggestion that the left and right halves of the brain work together.","D":"It disrupts the idea that the right hemisphere of the brain controls the left side of the body."},"answer":""},{"n":49,"stem":"What belief have neuroscientists long rejected according to the passage?","options":{"A":"There are left-dominant people and right-dominant people with different personalities.","B":"There are noticeable differences between the left and right hemispheres of the brain.","C":"One's personality is hardly related to the different halves of the brain.","D":"Different areas of the brain are responsible for different activities."},"answer":""},{"n":50,"stem":"What are we advised to do with an online quiz that tells us something about ourselves?","options":{"A":"Challenge its authority.","C":"Evaluate its popularity.","B":"Scrutinize its originality.","D":"Question its reliability."},"answer":""}]},{"title":"Passage Two","passage":"One hundred thirty-five students, four teachers, one giant classroom: This is what 9th grade looks like at\nWestwood High School, in Mesa, Arizona's largest school system. There, an innovative teaching model has\ntaken hold, and is spreading to other schools in the district and beyond.\n     Five years ago, faced with high teacher turnover and declining student enrollment, Westwood's leaders\ndecided to try something different. Working with professors at Arizona State University's teachers college, they\npiloted a classroom model known as team teaching, which allows teachers to dissolve the walls that separate\ntheir classes across physical or grade divides.\n     The teachers share large groups of students-sometimes 100 or more-and rotate between group instruction,\none-on-one interventions, small study groups, or whatever the teachers as a team agree is a priority that day.\nWhat looks at times like chaos is in fact a carefully orchestrated plan: Each morning, the Westwood teams meet\nto hammer out a personalized program for every student the team will focus on that day.\n     By giving teachers more opportunity to collaborate, Mesa's administrators hoped to fill staffing gaps and\nboost teacher morale and retention. Initial research suggests the gamble could pay off.\n     \"Teachers are doing fantastic things, but it's very rare a teacher walks into another room to see what's\nhappening,\" said Andi Fourlis, superintendent of Mesa Public Schools. \"Our profession is so slow to advance\nbecause we are working in isolation.\"\n     Of course, overhauling teaching approaches can't fix all the frustrations teachers have, such as low pay,\nbut early results from Mesa show team teaching may be helping to reverse low morale. In a survey of hundreds\nof the district's teachers, researchers found those who worked on teams reported greater job satisfaction, more\nfrequent collaborations with colleagues, and more positive interactions with students.\n     Another benefit of teams, teachers say, is that they can help each other improve their instruction. During\none planning session, English teacher Jeff Hall shared a performance appraisal with a science teacher: Her\nrecent lecture on something she called \"the central dogma of biology\" had bewildered him and their other\nteammates.\n     \"If the science is too confusing for me, can you imagine the frustration you feel as kids?\" Hall said. But\nthe science teacher, he said, wouldn't have known about the confusion on her own.\n     The model is not for everyone. Some teachers approached about volunteering for a team have said they\nprefer to work alone. Team teaching can also be a scheduling nightmare, especially at schools like Westwood\nwhere only some staff work in teams. There are also thorny questions like how to evaluate four teachers on the\n\n                                   2024 年 12 月英语六级真题第 3 套           第 6 页，共 7 页\n\nperformance of 135 students. But for the time being, it seems to be working.","questions":[{"n":51,"stem":"What do we learn about team teaching from the passage?","options":{"A":"It is generally conducted in classrooms without walls.","B":"It allows students to choose teachers they favor most.","C":"It prioritizes peer work over classroom instruction.","D":"It is closely coordinated despite seeming confusion."},"answer":""},{"n":52,"stem":"What does initial research suggest regarding Westwood's innovative teaching model?","options":{"A":"It could help raise teachers' pay.","C":"It could cut down overall costs.","B":"It could turn out to be a success.","D":"It could end up like a gamble."},"answer":""},{"n":53,"stem":"What did superintendent Andi Fourlis say about the teaching profession?","options":{"A":"Morale cannot be boosted until teaching models are overhauled.","B":"Teachers are simply too busy to visit classes of their colleagues.","C":"Progress is slow due to lack of collaboration among teachers.","D":"Teachers often do fantastic things without being noticed."},"answer":""},{"n":54,"stem":"What does the author want to show by citing English teacher Jeff Hall's experience?","options":{"A":"English teachers and science teachers are complementary in performing their tasks.","B":"A teacher of arts and letters is completely puzzled by what a science teacher teaches.","C":"The new teaching model helps inform the teacher how their instruction is received.","D":"Science teachers will hardly know the confusion they create without a performance appraisal."},"answer":""},{"n":55,"stem":"What does the author think is one of the difficult problems in implementing the new teaching model?","options":{"A":"What to do with teachers working alone.","C":"How to recruit volunteers for a team.","B":"What to include in teaching schedules.","D":"How to assess each teacher's performance."},"answer":""}]}],"translation":{"prompt":"","guide":[]}});})();
